/**
 * Steps pointing at the parts of a page (`design/components/tour.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tour.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/dialog'
import { normalizeProps } from '@zag-js/solid'

import {
  afresh,
  agentMember,
  claimSlot,
  classes,
  createCell,
  createDerived,
  elementRef,
  mergeParts,
  revealTourTarget,
  scope,
  tourPlacement,
  tourTarget,
  tourTargetRect,
  tourViewport,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/tour.module.css'
import Button from '../controls/Button'

export interface TourStep {
  /** The step's key, unique in the tour. */
  id: string
  /** The `name` of the `Tour.Target` the step points at. Without one, the step is drawn centred. */
  target?: string
  title: string
  /** A sentence or two about the target, as text. */
  body: string
  /** The side of the target the panel opens on, when it fits there. */
  side?: 'top' | 'right' | 'bottom' | 'left'
}

export interface TourMessages {
  next: string
  previous: string
  /** The last step's forward control, which ends the tour. */
  done: string
  /** The close control's accessible name. */
  close: string
  /** The position line, counting from 1: "Step 2 of 5". */
  position: (position: number, count: number) => string
}

export type TourEnd = 'finished' | 'dismissed'

export interface TourProps {
  defaultOpen?: boolean
  defaultStep?: number
  messages?: TourMessages
  /**
   * Called when the reader ends the tour, with why. A tour never opens itself, so its end is the
   * one change it reports. The member stores nothing: the application records that the tour was
   * seen.
   */
  onEnd?: (reason: TourEnd) => void
  onStepChange?: (index: number) => void
  open?: boolean
  /**
   * The current step's index, clamped to the steps.
   */
  step?: number
  steps: readonly TourStep[]
}

/** Steps pointing at the parts of a page. */
export default function Tour(given: TourProps): JSX.Element {
  const props = mergeProps(
    {
      messages: (() => ({
        next: 'Next',
        previous: 'Previous',
        done: 'Done',
        close: 'Close',
        position: (position: number, count: number) => `Step ${position} of ${count}`,
      }))(),
    } as Defaults<TourProps, 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const positioner = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const uncontrolledStep = createCell(props.defaultStep ?? 0)
    const ending = createCell(null as 'finished' | 'dismissed' | null)
    const geometry = createCell(
      null as {
        x: number
        y: number
        placement: 'top' | 'right' | 'bottom' | 'left' | 'center'
        hole: { x: number; y: number; width: number; height: number } | null
      } | null,
    )
    const count = createDerived(() => props.steps.length)
    const index = createDerived(() =>
      Math.min(Math.max(props.step ?? uncontrolledStep.value, 0), Math.max(count.value - 1, 0)),
    )
    const current = createDerived(() => props.steps[index.value])
    const first = createDerived(() => index.value === 0)
    const last = createDerived(() => index.value === count.value - 1)
    const drawnAt = createDerived(() => geometry.value?.placement ?? 'center')
    const cutOut = createDerived(() => geometry.value?.hole ?? null)
    const go = createDerived(() => (next: number): void => {
      uncontrolledStep.value = next
      props.onStepChange?.(next)
    })
    const closed = createDerived(() => (open: boolean): void => {
      if (open) return
      const reason = ending.value ?? 'dismissed'
      ending.value = null
      props.onEnd?.(reason)
    })
    const place = createDerived(() => (): void => {
      if (positioner.value == null || current.value === undefined) return
      const rect = tourTargetRect(tourTarget(current.value.target))
      const next = {
        ...tourPlacement(
          rect,
          { width: positioner.value.offsetWidth, height: positioner.value.offsetHeight },
          tourViewport(),
          current.value.side,
        ),
        hole: rect,
      }
      if (JSON.stringify(next) !== JSON.stringify(geometry.value)) geometry.value = next
    })
    const follow = createDerived(() => (): (() => void) => {
      const again = (): void => place.value()
      window.addEventListener('resize', again)
      document.addEventListener('scroll', again, { capture: true, passive: true })
      return () => {
        window.removeEventListener('resize', again)
        document.removeEventListener('scroll', again, { capture: true })
      }
    })
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open === undefined ? undefined : props.open && count.value > 0,
          defaultOpen: props.defaultOpen === true && count.value > 0,
          preventScroll: false,
          closeOnInteractOutside: false,
          initialFocusEl: () => panel.value,
          onOpenChange: (details) => {
            closed.value(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const end = createDerived(() => (reason: 'finished' | 'dismissed'): void => {
      ending.value = reason
      api.value.setOpen(false)
    })
    const show = createDerived(() => (): void => {
      if (!api.value.open || current.value === undefined) return
      revealTourTarget(tourTarget(current.value.target))
      place.value()
      requestAnimationFrame(() => place.value())
    })
    const scrimPresent = usePresence(
      () => api.value.open && current.value !== undefined,
      () => scrim.value,
      'dialog.scrim',
    )
    const panelPresent = usePresence(
      () => api.value.open && current.value !== undefined,
      () => panel.value,
      'popover.panel',
      {
        get side() {
          return drawnAt.value === 'center' ? undefined : drawnAt.value
        },
        align: 'center',
      },
    )
    const effect1 = () => {
      show.value()
    }
    watchEffect(
      createMemo(() => [api.value.open, index.value]),
      effect1,
      true,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const run = () => {
        place.value()
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [positioner.value]) if (element) resize?.observe(element)
      release2 = () => {
        resize?.disconnect()
      }
      run()
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect2,
      true,
    )
    onCleanup(() => release2?.())
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = follow.value()
      release3 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect3,
      true,
    )
    onCleanup(() => release3?.())
    const effect4 = () => {
      void (api.value.open && panel.value?.focus())
    }
    watchEffect(
      createMemo(() => index.value),
      effect4,
      false,
    )
    let release5: (() => void) | undefined
    const effect5 = () => {
      release5?.()
      const ran = agentMember({
        member: 'Tour',
        element: () => panel.value,
        state: () => ({
          open: api.value.open,
          step: index.value,
          steps: props.steps.map((each) => ({ id: each.id, title: each.title, body: each.body })),
        }),
        actions: {
          next: () =>
            (() => {
              if (!api.value.open) throw new Error('The tour is not open.')
              if (last.value)
                throw new Error('On the last step, an agent ends a tour with dismiss.')
              go.value(index.value + 1)
            })(),
          previous: () =>
            (() => {
              if (!api.value.open) throw new Error('The tour is not open.')
              if (first.value) throw new Error('This is the first step.')
              go.value(index.value - 1)
            })(),
          dismiss: () => api.value.open && end.value('dismissed'),
        },
        withholds: () => panel.value,
      })
      release5 = () => {
        ran()
      }
    }
    onMount(effect5)
    onCleanup(() => release5?.())
    return (
      <Portal>
        {afresh(() => (
          <>
            {scrimPresent() ? (
              <div
                {...mergeParts(api.value.getBackdropProps(), {
                  class: classes(
                    cutOut.value !== null ? styles.spotlight : undefined,
                    cutOut.value === null ? styles.scrim : undefined,
                  ),
                  style: {
                    '--pm-tour-hole-x': cutOut.value === null ? undefined : `${cutOut.value.x}px`,
                    '--pm-tour-hole-y': cutOut.value === null ? undefined : `${cutOut.value.y}px`,
                    '--pm-tour-hole-width':
                      cutOut.value === null ? undefined : `${cutOut.value.width}px`,
                    '--pm-tour-hole-height':
                      cutOut.value === null ? undefined : `${cutOut.value.height}px`,
                  },
                  hidden: undefined,
                  'aria-hidden': 'true',
                  'data-tour-part': 'scrim',
                })}
                ref={scrim.attach}
              />
            ) : null}
            {panelPresent() ? (
              <div
                {...mergeParts(api.value.getPositionerProps(), {
                  class: styles.positioner,
                  style: {
                    '--pm-tour-x': `${geometry.value?.x ?? 0}px`,
                    '--pm-tour-y': `${geometry.value?.y ?? 0}px`,
                  },
                  'data-placement': drawnAt.value,
                })}
                ref={positioner.attach}
              >
                {/* panel */}
                <div
                  {...mergeParts(api.value.getContentProps(), {
                    class: styles.panel,
                    hidden: undefined,
                    'data-step': current.value?.id,
                    'data-member': 'tour',
                  })}
                  ref={panel.attach}
                >
                  {/* title */}
                  <h2 {...mergeParts(api.value.getTitleProps(), { class: styles.title })}>
                    {current.value?.title}
                  </h2>
                  {/* description */}
                  <div
                    {...mergeParts(api.value.getDescriptionProps(), { class: styles.description })}
                  >
                    {/* body */}
                    <p class={styles.body}>{current.value?.body}</p>
                    {/* position */}
                    <p class={styles.position} data-tour-part="position">
                      {props.messages.position(index.value + 1, count.value)}
                    </p>
                  </div>
                  {/* actions */}
                  <div class={styles.actions} data-tour-part="actions">
                    {!first.value ? (
                      <Button
                        variant="outline"
                        tone="neutral"
                        size="sm"
                        label={props.messages.previous}
                        onClick={() => go.value(index.value - 1)}
                      />
                    ) : null}
                    <Button
                      size="sm"
                      label={last.value ? props.messages.done : props.messages.next}
                      onClick={() =>
                        last.value ? end.value('finished') : go.value(index.value + 1)
                      }
                    />
                  </div>
                  {/* close */}
                  <div class={styles.close} data-tour-part="close">
                    <Button
                      variant="ghost"
                      tone="neutral"
                      size="sm"
                      iconOnly={true}
                      icon="close"
                      label={props.messages.close}
                      onClick={() => end.value('dismissed')}
                    />
                  </div>
                </div>
              </div>
            ) : null}
          </>
        ))}
      </Portal>
    )
  })
}
